package nl.smartstreamlabs.sbwdroneconfig;
import net.minecraft.core.*;import net.minecraft.nbt.*;import net.minecraft.server.level.*;import net.minecraft.world.entity.*;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.*;import net.minecraft.world.level.saveddata.SavedData;import java.util.*;
/** Dimension-local persistent links. Unloaded records remain distinct from removed structures. */
public final class DefenseData extends SavedData{
 public static final class Site{public final UUID id;public final int kind;public final BlockPos root;public final Direction face;public final UUID owner;public final String name;public UUID radar;public boolean removed;public final LinkedHashSet<UUID>links=new LinkedHashSet<>();Site(UUID id,int kind,BlockPos root,Direction face,UUID owner,String name){this.id=id;this.kind=kind;this.root=root.immutable();this.face=face;this.owner=owner;this.name=name;}}
 private final Map<UUID,Site>sites=new LinkedHashMap<>();private final Map<Long,Set<UUID>>chunks=new HashMap<>();private final Map<UUID,Lease>leases=new HashMap<>();private record Lease(UUID target,long until){}
 public static DefenseData get(ServerLevel l){return l.getDataStorage().computeIfAbsent(new SavedData.Factory<>(DefenseData::new,DefenseData::load),"sbw_defense_network");}
 public Site site(UUID id){return id==null?null:sites.get(id);}public void register(Site s){if(sites.containsKey(s.id))return;sites.put(s.id,s);index(s);setDirty();}
 private void index(Site s){if(s.kind==3){for(var c:AdcGeometry.MODEL.cells){var p=AdcGeometry.MODEL.cell(s.root,s.face,c);chunks.computeIfAbsent(new ChunkPos(p).toLong(),v->new HashSet<>()).add(s.id);}return;}if(s.kind>=2)return;for(var c:DefenseGeometry.MODELS[s.kind].cells){var p=DefenseGeometry.MODELS[s.kind].cell(s.root,s.face,c);chunks.computeIfAbsent(new ChunkPos(p).toLong(),v->new HashSet<>()).add(s.id);}}
 public static boolean allowed(ServerLevel l,UUID owner,String name,Player p){if(p==null)return false;if(p.hasPermissions(2)||owner==null||owner.equals(p.getUUID()))return true;var team=l.getScoreboard().getPlayersTeam(name);return team!=null&&team.isAlliedTo(l.getScoreboard().getPlayersTeam(p.getScoreboardName()));}
 private boolean compatible(ServerLevel l,Site a,Site b){if(a.owner==null||b.owner==null)return false;if(a.owner.equals(b.owner))return true;var x=l.getScoreboard().getPlayersTeam(a.name);var y=l.getScoreboard().getPlayersTeam(b.name);return x!=null&&y!=null&&x.isAlliedTo(y);}
 public DefenseBlockEntity radar(ServerLevel l,UUID id){var s=site(id);return s!=null&&!s.removed&&s.kind==1&&l.hasChunkAt(s.root)&&l.getBlockEntity(s.root)instanceof DefenseBlockEntity b&&b.id.equals(id)?b:null;}
 public PatriotLauncher launcher(ServerLevel l,UUID id){var s=site(id);if(s==null||s.removed)return null;if(s.kind==3)return l.hasChunkAt(s.root)&&l.getBlockEntity(s.root)instanceof AdcBlockEntity a&&a.id.equals(id)?a:null;if(s.kind==4)return l.getEntity(id)instanceof Ndc01Entity n?n:null;if(s.kind==2)return l.getEntity(id)instanceof Mpl01Entity m?m:null;return s.kind==0&&l.hasChunkAt(s.root)&&l.getBlockEntity(s.root)instanceof DefenseBlockEntity b&&b.id.equals(id)?b:null;}
 public String link(ServerLevel l,UUID radarId,UUID launcherId,ServerPlayer p){var radar=site(radarId);var launcher=site(launcherId);if(radar==null||launcher==null||radar.removed||launcher.removed||radar.kind!=1||launcher.kind==1)return "INVALID";if(!allowed(l,radar.owner,radar.name,p)||!allowed(l,launcher.owner,launcher.name,p)||!compatible(l,radar,launcher))return "DENIED";var r=radar(l,radarId);var v=launcher(l,launcherId);if(r==null||v==null)return "UNLOADED";if(r.defensePosition().distanceToSqr(v.defensePosition())>Math.pow(DefenseConfig.LINK_RANGE.get(),2))return "TOO_FAR";if(!radar.links.contains(launcherId)&&radar.links.size()>=DefenseConfig.LINKS.get())return "LINK_LIMIT";unlink(launcherId);launcher.radar=radarId;radar.links.add(launcherId);setDirty();r.changed();if(v instanceof DefenseBlockEntity b)b.changed();if(v instanceof AdcBlockEntity a)a.changed();return "LINKED";}
 public boolean navalAllows(ServerLevel l,UUID radarId,UUID carrierId,ServerPlayer actor){var r=radar(l,radarId);var a=site(radarId);var b=site(carrierId);var carrier=launcher(l,carrierId);return r!=null&&r.active()&&a!=null&&b!=null&&b.kind==4&&Objects.equals(b.radar,radarId)&&a.links.contains(carrierId)&&compatible(l,a,b)&&carrier!=null&&r.defensePosition().distanceToSqr(carrier.defensePosition())<=Math.pow(DefenseConfig.LINK_RANGE.get(),2)&&(actor==null?r.automatic:allowed(l,a.owner,a.name,actor)&&allowed(l,b.owner,b.name,actor));}
 public void unlink(UUID launcherId){var s=site(launcherId);if(s==null)return;var r=site(s.radar);if(r!=null)r.links.remove(launcherId);s.radar=null;leases.remove(launcherId);setDirty();}
 public boolean radarAllows(ServerLevel l,UUID radarId,UUID launcherId,ServerPlayer actor,boolean automatic){var r=radar(l,radarId);var s=site(launcherId);return r!=null&&r.active()&&s!=null&&radarId.equals(s.radar)&&site(radarId).links.contains(launcherId)&&compatible(l,site(radarId),s)&&launcher(l,launcherId)!=null&&r.defensePosition().distanceToSqr(launcher(l,launcherId).defensePosition())<=Math.pow(DefenseConfig.LINK_RANGE.get(),2)&&(automatic?r.automatic:actor!=null&&r.canOperate(actor)&&allowed(l,s.owner,s.name,actor));}
 public boolean cannonAssigned(ServerLevel l,UUID target,UUID except){leases.values().removeIf(v->v.until<l.getGameTime());return leases.entrySet().stream().anyMatch(e->!e.getKey().equals(except)&&e.getValue().target.equals(target))||PatriotShots.assigned(l,target)>0;}
 public void reserve(UUID launcher,UUID target,long now){leases.put(launcher,new Lease(target,now+40));}public void release(UUID launcher){leases.remove(launcher);}public boolean assigned(ServerLevel l,UUID target){leases.values().removeIf(v->v.until<l.getGameTime());int pending=(int)leases.values().stream().filter(v->v.target.equals(target)).count();return pending+PatriotShots.assigned(l,target)>=DefenseConfig.ASSIGNMENT.get();}
 public void removeAt(ServerLevel l,BlockPos root,int kind){for(var id:List.copyOf(chunks.getOrDefault(new ChunkPos(root).toLong(),Set.of()))){var s=site(id);if(s!=null&&s.kind==kind&&s.root.equals(root)){remove(l,id);return;}}}
 public void remove(ServerLevel l,UUID id){var s=site(id);if(s==null||s.removed)return;unlink(id);for(var child:List.copyOf(s.links))unlink(child);s.links.clear();s.removed=true;setDirty();clean(l,s);}
 private void clean(ServerLevel l,Site s){if(s.kind==3){if(l.hasChunkAt(s.root)&&l.getBlockEntity(s.root)instanceof AdcBlockEntity a&&!a.removing()){if(!a.id.equals(s.id)){erase(s);return;}a.remove(null,true);return;}boolean pending=false;AdcBlock.MUTATING.set(true);try{for(var c:AdcGeometry.MODEL.cells){var at=AdcGeometry.MODEL.cell(s.root,s.face,c);if(!l.hasChunkAt(at)){pending=true;continue;}var state=l.getBlockState(at);if(state.getBlock()instanceof AdcBlock&&AdcBlock.root(at,state).equals(s.root))l.removeBlock(at,false);}}finally{AdcBlock.MUTATING.set(false);}if(!pending)erase(s);return;}if(s.kind==2||s.kind==4){erase(s);return;}boolean pending=false;boolean old=DefenseBlock.MUTATING.get();DefenseBlock.MUTATING.set(true);try{var geo=DefenseGeometry.MODELS[s.kind];for(var c:geo.cells){var p=geo.cell(s.root,s.face,c);if(!l.hasChunkAt(p)){pending=true;continue;}var state=l.getBlockState(p);if(state.getBlock()instanceof DefenseBlock b&&b.kind==s.kind&&DefenseBlock.root(p,state).equals(s.root))l.removeBlock(p,false);}}finally{DefenseBlock.MUTATING.set(old);}if(!pending)erase(s);}
 private void erase(Site s){sites.remove(s.id);for(var it=chunks.values().iterator();it.hasNext();){var v=it.next();v.remove(s.id);if(v.isEmpty())it.remove();}setDirty();}
 public void chunk(ServerLevel l,long key){for(var id:List.copyOf(chunks.getOrDefault(key,Set.of()))){var s=site(id);if(s==null)continue;if(!s.removed&&l.hasChunkAt(s.root)&&!(s.kind==3?l.getBlockState(s.root).getBlock()instanceof AdcBlock:l.getBlockState(s.root).getBlock()instanceof DefenseBlock))remove(l,id);else if(s.removed)clean(l,s);}}
 public static DefenseData load(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){var d=new DefenseData();for(var v:n.getList("Sites",10)){var t=(CompoundTag)v;var s=new Site(t.getUUID("Id"),t.getInt("Kind"),BlockPos.of(t.getLong("Root")),Direction.from2DDataValue(t.getInt("Facing")),t.hasUUID("Owner")?t.getUUID("Owner"):null,t.getString("Name"));s.removed=t.getBoolean("Removed");s.radar=t.hasUUID("Radar")?t.getUUID("Radar"):null;for(var x:t.getList("Links",10))s.links.add(((CompoundTag)x).getUUID("Id"));d.sites.put(s.id,s);d.index(s);}return d;}
 @Override public CompoundTag save(CompoundTag n,net.minecraft.core.HolderLookup.Provider registry){var list=new ListTag();for(var s:sites.values()){var t=new CompoundTag();t.putUUID("Id",s.id);t.putInt("Kind",s.kind);t.putLong("Root",s.root.asLong());t.putInt("Facing",s.face.get2DDataValue());if(s.owner!=null)t.putUUID("Owner",s.owner);t.putString("Name",s.name);t.putBoolean("Removed",s.removed);if(s.radar!=null)t.putUUID("Radar",s.radar);var children=new ListTag();for(var id:s.links){var c=new CompoundTag();c.putUUID("Id",id);children.add(c);}t.put("Links",children);list.add(t);}n.put("Sites",list);return n;}
}
